export default {"v":1,"salt":"e1d0cc68a242860f3ddd2c4531ffa410","pass":95,"count":20,"questions":[{"id":"req1","topic":"Documents needed to rent","clause":"Rental requirements","always":true,"q":"You want to rent a car this weekend. Which set of documents do you need to bring?","options":[["a","Just my driver's license. Proof of address shouldn't matter if I have a license."],["b","A valid driver's license and one recent proof of address in my name, plus a copy of my car insurance card instead of the second proof."],["c","A valid driver's license, plus at least 2 recent proofs of address in my own name (utility bill, paystub or bank statement)."],["d","A photo of my license on my phone and my friend's address, since I'm staying with them."]],"k":"d3e414e20e192b096e4fa16516a9b2cfe1ca13fb8b001b3b3eb95f1fa8257783"},{"id":"req2","topic":"What counts as proof of address","clause":"Rental requirements","always":true,"q":"Which of these can count as one of your proofs of address?","options":[["a","My roommate's electricity bill, since it's for the place where I live."],["b","A recent internet or phone bill, a recent paystub, or a recent bank statement, in my own name."],["c","A recent shipping label or a piece of junk mail with my name and address, since it shows where I receive mail."],["d","My lease from three years ago. The address is still on it."]],"k":"ccc7c8493c420145bdf4bb534a404a4885d2636a2df1aeb519656660682a74c3"},{"id":"req3","topic":"Accepted payment methods","clause":"Rental requirements; Payment","always":true,"q":"How can you pay for your rental?","options":[["a","Cash, Apple Pay, Venmo, Chime or Zelle."],["b","I'll pay when I bring the car back, after I see how much I used it."],["c","Cash, Apple Pay, Venmo or Zelle, or a personal check if I don't have those, as long as it clears before the trip ends."],["d","Any method I prefer. The owner should adapt to me."]],"k":"32cfe45865d4c7305d04ed70ff234730b6fd67beb19f157f96194f82d939e11e"},{"id":"req4","topic":"License status","clause":"Rental requirements","always":false,"q":"Your driver's license is currently suspended, but you have a valid state ID. Can you rent?","options":[["a","Yes, an ID proves who I am, that's what matters."],["b","Yes, as long as I bring a valid state ID and proof of address, and show the letter proving my suspension ends next month, since the suspension is only temporary."],["c","Yes, my friend with a valid license can rent it and I'll drive."],["d","No. I need a valid driver's license, and only the drivers listed on the agreement may drive."]],"k":"2aca990dc669e16f763968267720e25aecba8815e88e4fe83ae4f69dcd15126f"},{"id":"req5","topic":"Name on documents","clause":"Rental requirements","always":false,"q":"Your bills are in your partner's name and your paystub shows an old address. What should you do?","options":[["a","Bring them anyway. The owner probably won't check names that closely."],["b","Tell the owner before booking. My proofs must be recent and in my own name, so I need to bring 2 documents that meet that."],["c","Edit the PDF of the bill to show my name."],["d","Bring my partner's bills with a signed note from my partner saying I live there, plus my old paystub. That should be enough since it's the same household."]],"k":"baef703123106e4a58e808dc11a3c6c3ee79ec9755bfb8f499ba6725aafb6511"},{"id":"tire1","topic":"Nail in the tire","clause":"Vehicle Condition; Guest Financial Responsibility","always":false,"q":"You notice a nail in a tire and the tire pressure warning comes on. What do you do?","options":[["a","Keep driving until the trip ends. Tires are the owner's problem."],["b","Stop driving on it, put on the spare or call the owner right away, and pay for the repair since it happened during my rental."],["c","Drive on it until it goes flat, then leave the car where it stopped."],["d","Keep driving carefully and check the pressure at a gas station every day, then mention it at return so the owner can get it fixed during normal maintenance."]],"k":"1bfd4d22f74e4a5db39847acbaff4b82894cbcd9ceed0aa196cd8799b8734e21"},{"id":"tire2","topic":"Driving on a flat, rim damaged","clause":"Guest Financial Responsibility; Diminished Value","always":false,"q":"You kept driving on a flat tire. Now the tire is destroyed and the rim is scratched. Who pays?","options":[["a","The owner. Tires wear out, that's a cost of doing business."],["b","Nobody. A nail is nobody's fault."],["c","I pay for the tire, the rim repair and any related costs. Damage during my rental is my responsibility, regardless of fault."],["d","I pay for the tire only, since the nail was bad luck. The rim scratches are normal wear and tear the owner would have to fix at some point anyway."]],"k":"d5ebbdd7b8e712e285f2ed0545bc5694904249aba8a73ae5c680df823460a97d"},{"id":"tire3","topic":"Tires worn by rideshare driving","clause":"Use Restrictions","always":false,"q":"On a regular rental (not Rent-to-Own), you used the car for DoorDash and Uber without asking, and the tires wore down much faster than normal. What applies?","options":[["a","Nothing. Miles are miles; the owner can't tell what I used it for."],["b","It's fine as long as I stayed under the mileage limit."],["c","Rideshare and delivery use without the owner's written consent is prohibited. I'm in breach, and I pay for the excess wear and any damage."],["d","It's fine because I stayed under the 200 miles per day limit, and delivery apps don't wear a car any more than normal driving, so no extra charges apply."]],"k":"2b27e14892704f7eb16cdf5dd583a3a76062ce744ff3f6aaae26e5bece3d46e5"},{"id":"ret1","topic":"Leaving the car somewhere","clause":"Vehicle Return, Failure to Return & Repossession","always":false,"q":"The car has a problem, so you leave it in a store parking lot and text the owner the location. What applies?","options":[["a","Nothing. I told them where it is, so the rental is over."],["b","I'm still responsible: the car must be returned to the agreed location. Retrieval fees ($1,500, plus $500 if recovered elsewhere), loss of use ($250/day) and damage can be charged to me."],["c","I'm responsible only for a normal tow, around $100, because I told the owner exactly where the car is, and the rental officially ends once I share the location in writing."],["d","The owner should send a tow truck at their own expense; that's normal."]],"k":"98de175e8341d275ed17101d6df65dfe3bd9a3dd4ca91bb7270697ffdaa6107d"},{"id":"ret2","topic":"Running late","clause":"Timely Return","always":false,"q":"You need the car one extra day. What's the right way to handle it?","options":[["a","Keep it. One day late is no big deal, I'll pay later."],["b","Turn my phone off so the owner can't bother me."],["c","Ask the owner before the trip ends. An extension only counts if the owner confirms it in writing (text or email)."],["d","Keep the car and text the owner that I'll be a day late. If they don't reply, that counts as an approved extension, because I informed them in writing."]],"k":"db92d8abd3e8e028075a9bfb8d0426b1e57ef1c08d1a34cf28c088e5372fda73"},{"id":"ret3","topic":"Not returning the car","clause":"Failure to Return; Florida Statute 812.155","always":false,"q":"Your trip ended two days ago and you still have the car without an approved extension. What are the consequences?","options":[["a","None as long as I eventually bring it back."],["b","The normal daily rate for the two days, and since I'm paying, it can't be considered unauthorized possession."],["c","Only the normal daily rate for the extra days. The owner must wait out a 5-day grace period under Florida law before reporting anything, whatever I signed."],["d","Liquidated damages ($250 per day of loss of use, retrieval fees), and the car may be reported as stolen under Florida law. I agreed to immediate retrieval after a Notice of Termination."]],"k":"527dc187beb2bedaddc98507ba87fe152293b108f7664869a316cc7c9161c751"},{"id":"ret4","topic":"Notice of Termination","clause":"Notice of Termination & Immediate Retrieval","always":false,"q":"The owner sends you a text: Notice of Termination, return the car now. What does that mean?","options":[["a","I can ignore it until my original trip end date."],["b","Keeping the car after that notice is unauthorized possession. The owner may involve law enforcement or recovery agents immediately."],["c","I still have 5 days before anything can happen, because Florida law gives every renter a 5-day grace period no matter what the agreement says or what notice is sent."],["d","I can negotiate by not answering until they calm down."]],"k":"db5b8e3ad2660bde4350e2bf23e439e0179c3fd4108e517d8d6996fdd3507874"},{"id":"ret5","topic":"Holding the car past the end date","clause":"Guest Financial Responsibility","always":false,"q":"You keep the car past your Trip End without an approved extension. What rate applies for those extra days?","options":[["a","My discounted weekly or monthly rate keeps going day by day, plus a $20 per day administrative late charge for each extra day I keep the car."],["b","No charge, the trip already ended."],["c","The full Daily Rate for each extra day or partial day, plus all other fees under the agreement."],["d","Whatever I think is fair."]],"k":"d1b9c178b046f425289d435d42b1f10091b13fb6b6c3942dcf94ecda95af2670"},{"id":"clean1","topic":"Smoking or vaping","clause":"Cleaning and Smoking Violations","always":false,"q":"You vaped in the car a few times with the windows down. What applies?","options":[["a","Nothing. Vaping isn't smoking."],["b","A $150 cleaning fee, but only if the smell is still strong at return. Vaping with the windows down doesn't count as smoking under most rental rules."],["c","Big rental companies don't charge for this, so this owner shouldn't either."],["d","Smoking of any kind, including vaping, is prohibited. A $250 deodorization and detailing fee applies, and the owner's photos are conclusive."]],"k":"d6a294008e617cbe885217a094ca8d216b7a9cb859bac967d206274ded850375"},{"id":"clean2","topic":"Returning the car dirty","clause":"Cleaning and Smoking Violations","always":false,"q":"You return the car with trash, sand and food stains inside. What should you expect?","options":[["a","Nothing. Cleaning cars is the owner's job."],["b","A cleaning fee of $150 (or $250 for biological waste, excessive mud or hazardous materials), because it must come back clean inside and out."],["c","A $50 cleaning fee at most, since a standard vacuum and wipe-down is already part of every rental, and food stains count as normal wear and tear."],["d","I'll argue it was like that when I got it, even though it wasn't."]],"k":"d16db945d95b74c16daf933ad17e6a53bfbdb8f26cdc9d345c07488d4dfde08e"},{"id":"clean3","topic":"Cigarette burns in the seats","clause":"Cleaning and Smoking; Guest Financial Responsibility","always":false,"q":"A passenger smoked and left small burn holes in the seat. What applies?","options":[["a","Not my problem, I wasn't the one smoking."],["b","I pay the $250 smoking fee only. The seat holes are cosmetic wear, so the seat repair is on the owner."],["c","I'm responsible for my passengers: I pay to repair or replace the seat, plus the $250 smoking fee."],["d","I'll put a towel over it and say nothing."]],"k":"8e2e938cff347f597c3b8280026d0371872ddd5b5f0c7289085bcbe6e4f9dc16"},{"id":"clean4","topic":"\"Avis doesn't charge me\"","clause":"General Provisions","always":false,"q":"You think: big rental companies never charge for smoke or trash, so this rental shouldn't either. Which statement is correct?","options":[["a","Right. If big companies don't, this owner can't."],["b","This agreement is what governs my rental. Its fees apply no matter what other companies do."],["c","I can choose which rules I follow."],["d","Fees here only apply if they match what Avis or Enterprise charge for the same thing, because Florida rental customers are entitled to industry-standard pricing."]],"k":"5c6d6412e30979c76a621af811047a63362ac852f35da96bdaf2020d830b881c"},{"id":"dmg1","topic":"Broken radio screen","clause":"Guest Financial Responsibility; Diminished Value","always":false,"q":"In a moment of anger you (or a passenger) hit the radio screen and it cracks. What do you do?","options":[["a","Return the car and not mention it. Maybe nobody will notice."],["b","Say it was already like that."],["c","Tell the owner right away and pay for the repair or replacement, plus any loss in value."],["d","Tell the owner at return, and pay only if the radio stops working completely. A cracked screen that still turns on is cosmetic wear, not damage."]],"k":"64851025c26b3122758a39b03973a387ecbbcbd501ad6b43f9188efe0faf6864"},{"id":"dmg2","topic":"Slashed or torn seats","clause":"Guest Financial Responsibility","always":false,"q":"You discover a seat was slashed during your rental while the car was parked. Who is responsible?","options":[["a","The person who did it, so I'm not involved."],["b","I am, regardless of fault: damage during my rental is my financial responsibility. I report it to the owner (and police if it was vandalism)."],["c","The owner's insurance covers vandalism automatically, so I file a police report and that settles it. Renters only pay for damage they cause themselves."],["d","No one, if I can't prove who did it."]],"k":"4566bdff70f3995dd362e58a49577d370eda20ced4ed2632919b0dda00ddf43b"},{"id":"dmg3","topic":"Driver's window broken in a break-in","clause":"Guest Financial Responsibility; Insurance","always":false,"q":"Someone breaks the driver's window while the car is parked. Which is correct?","options":[["a","It's a crime, so I owe nothing."],["b","I'll tape a plastic bag over it and keep driving for the rest of the week."],["c","I file a police report, tell the owner immediately, and I'm responsible for the damage up to my $3,000 deductible regardless of fault (my insurance is primary if I provided it)."],["d","I file a police report and tell the owner. Because it was a crime and not an accident, the owner's insurance pays and the $3,000 deductible doesn't apply to me."]],"k":"ae488625b7580469df2834f1e3af316f9a9440ef220c2bcc772474123d4e4d88"},{"id":"dmg4","topic":"Cracked windshield","clause":"Guest Financial Responsibility","always":false,"q":"A rock hits the windshield on the highway and a crack spreads. What do you do?","options":[["a","Nothing, rocks are nobody's fault."],["b","Tell the owner as soon as it happens. I'm responsible for the repair because it happened during my rental, regardless of fault."],["c","Wait and see if the owner notices at return."],["d","Tell the owner at return. Windshield cracks from road debris count as normal wear, so the owner handles the repair through their own glass coverage."]],"k":"85a8b7fff3fdb97911074865cfb2662e9d49c3c6f39adffc57adc109f15fb244"},{"id":"dmg5","topic":"Accident that's not your fault","clause":"Insurance & Guest's Financial Responsibility","always":false,"q":"Another driver hits you and it's clearly their fault. What is your responsibility to the owner?","options":[["a","I report it right away, but I owe nothing at all: the other driver's insurance pays for everything, the deductible doesn't apply when it isn't my fault, and the owner collects from them directly."],["b","I'm still responsible for the first $3,000 of damage (the deductible) regardless of fault, I report it right away, and my insurance is primary if I provided it."],["c","Only if the police say it's my fault."],["d","I'll let the owner deal with the other driver alone."]],"k":"d7fd620daa59eeb99b5dff2220c1ab5b2c34f32757e86230887227c10803ee99"},{"id":"dmg6","topic":"Diminished value","clause":"Diminished Value","always":false,"q":"After an accident the car is repaired, but it's now worth less because it has an accident history. Who covers that loss?","options":[["a","No one, the car is fixed."],["b","The owner, it's part of owning cars."],["c","I do. The diminished value is assessed by an independent professional appraiser."],["d","The owner, because once it's repaired the car is legally back to its original condition, and diminished value only matters for cars that are being sold."]],"k":"f849e17dc7043ec4049371c07c85a762b29fb7d40ec27995b5125ab684e36fe6"},{"id":"dmg7","topic":"Damage noticed at pickup","clause":"Vehicle Condition/Warranty Exclusion","always":false,"q":"At pickup you notice a scratch that isn't on the checkout photos. What should you do?","options":[["a","Say nothing and blame it on the owner if they ask later."],["b","Point it out and have it documented before I drive away. I had the chance to inspect, so undocumented damage can be charged to me."],["c","Take no photos; it's the owner's job."],["d","Take a photo for myself but drive off without telling the owner, so I can show it later if they ever ask about that scratch."]],"k":"fc622041e95921db684babccf2663d48182fd84e7ac4790f7abb8cfe8ac636a0"},{"id":"dmg8","topic":"Warning light while driving","clause":"Vehicle Condition","always":false,"q":"The check engine or low oil light comes on during your trip. What do you do?","options":[["a","Keep driving; it's a rental."],["b","Keep driving normally but avoid the highway, check the oil myself, and mention it at return if the light is still on by then."],["c","If the car seems unsafe, stop using it and notify the owner immediately."],["d","Wait until I return it and mention it if they ask."]],"k":"c75ee20346d28638b366603ca4bc6c65e6df2fd2c57ade4faf8142b13d0c8a5a"},{"id":"ins1","topic":"Insurance options","clause":"Insurance & Guest's Financial Responsibility","always":false,"q":"You don't have your own auto insurance. What applies?","options":[["a","I can drive uninsured; the car has insurance anyway."],["b","I must buy the owner's contingent coverage at $60 per week (prorated). It carries a $3,000 deductible, which I still owe for any damage."],["c","I buy the owner's contingent coverage at $60 per week, and that completely removes the $3,000 deductible, so I would owe nothing for any damage."],["d","The owner's insurance covers me 100% with no deductible."]],"k":"ef2330c2c899ced1720827d122d833954a89d5976166508dc87887e7dbbd1e14"},{"id":"ins2","topic":"Using your own insurance","clause":"Insurance Option 1","always":false,"q":"You want to use your own auto insurance. What does it require?","options":[["a","A current policy with liability coverage valid for the whole rental is enough. Comprehensive, collision and listing the owner as Loss Payee are optional extras."],["b","A current policy valid for the whole rental, with liability, comprehensive and collision, listing the owner as \"Loss Payee\". The owner may verify it."],["c","Any card, even an expired one."],["d","Liability only is enough."]],"k":"7699f01458a065996308332c717234f99618a8a32dc00f5c26bcc672211d8b03"},{"id":"dep1","topic":"Security deposit","clause":"Security Deposit","always":false,"q":"You rent for 5 days. What about the security deposit?","options":[["a","Deposits are optional, I'll skip it."],["b","It's required for rentals of 7 days or less, and it's refunded at return if the car comes back undamaged, clean, with all keys, no smoking, no unpaid fees, on time and at the right place."],["c","It's required for every rental of any length, paid by card, and refunded automatically within 30 days by bank transfer after the owner inspects the car."],["d","I can pay it after the trip."]],"k":"7a5e4dd636481909721fa220fc1033b9b9d66cef204e831ab706180085c61c76"},{"id":"use1","topic":"Letting someone else drive","clause":"Use Restrictions; Trip Details","always":false,"q":"Your friend wants to drive the car for an evening. What's allowed?","options":[["a","Sure, I trust my friend."],["b","Only drivers listed on the agreement may drive. Lending or subleasing the car is not allowed without the owner's written consent."],["c","It's fine as long as my friend has a valid license and I stay in the car the whole time, because I'm still the responsible renter on the agreement."],["d","I'll let them drive and not tell the owner."]],"k":"e651df450031c4e3ec0de2d3c85b56397d109dc0ad436c73c62b1fab22ad9f64"},{"id":"use2","topic":"Leaving Florida","clause":"Geographic Restrictions and Vehicle Monitoring","always":false,"q":"You want to drive to Atlanta for the weekend. What applies?","options":[["a","I can go anywhere; it's my rental."],["b","Leaving Florida requires the owner's prior written consent. Taking it out of state without consent is a fundamental breach, and the owner may locate the car by GPS."],["c","Leaving Florida is fine without asking as long as I'm back on time, stay under my included miles, and keep the car's GPS on so the owner can see where it is."],["d","I'll disable the GPS so it doesn't matter."]],"k":"da51d49a909827fa63c6c3f85567846020e263dad9c8323b83b65cf0ed58ec96"},{"id":"use3","topic":"Towing and racing","clause":"Use Restrictions","always":false,"q":"On a regular rental, which of these uses of the car is allowed?","options":[["a","Towing a friend's small trailer to the beach, since the car has a hitch and it's only a few miles."],["b","Racing a friend on an empty road at night."],["c","Normal personal driving within Florida by the listed drivers."],["d","Using it as a rideshare car on weekends."]],"k":"b773cbab9303058d0448e5654832d261e465faf368ee18d2c601b618f0416edb"},{"id":"fee1","topic":"Fuel","clause":"Fuel, Tolls, and Violations (a)","always":false,"q":"You return the car with a quarter tank. What happens?","options":[["a","Nothing; gas is included."],["b","I'm charged $10 per gallon to refill it, plus a $25 service fee. It must come back full, with the correct fuel grade."],["c","The owner should refill it; that's their job."],["d","The owner refills it at the pump price and I pay only the actual cost of the missing fuel, with no service fee added."]],"k":"9d5cebe18aecc5432f5af27d2a5dd908f569727e529021d99c3cc000a0482129"},{"id":"fee2","topic":"Tolls","clause":"Fuel, Tolls, and Violations (b)","always":false,"q":"Tolls from your trip are billed to the owner's SunPass. What applies?","options":[["a","The owner pays; tolls come with the car."],["b","I reimburse every toll, plus a $5 administrative fee per transaction."],["c","I reimburse the tolls at cost. Administrative fees only apply to parking tickets."],["d","Tolls don't count if I didn't see a booth."]],"k":"db1e9613e2ee07d6a38bc170ffb8a81e6bf1a5ff4456a97425fc900895b455df"},{"id":"fee3","topic":"Tickets and camera fines","clause":"Fuel, Tolls, and Violations (c)","always":false,"q":"A red-light camera ticket arrives at the owner's address a month after your rental. Who pays?","options":[["a","The owner; it's their car."],["b","I pay the fine itself, but the owner can't add a fee because they only have to forward it."],["c","I pay the fine in full, plus a $50 administrative fee for processing it."],["d","I'll say it must have been another renter, even though the date matches my trip."]],"k":"b5609b146d97bde38c87677648afa0ccc6e1df3195fb283792ca66d4821cde5e"},{"id":"fee4","topic":"Chargebacks","clause":"Payment and Chargebacks","always":false,"q":"After the rental you're unhappy about a fee you agreed to, so you think about disputing the payment with your bank. What applies?","options":[["a","Banks always side with customers, so it's free money."],["b","Disputing a valid charge I authorized is a material breach: a $250 administrative fee applies, the owner sends the signed agreement as proof, and fraud may be reported as theft of services."],["c","I can dispute anything I want with no consequences."],["d","I can dispute it as long as I explain to my bank that I disagree with the fee. Since the bank decides, there's no fee or breach on my side."]],"k":"ca5871313d46c6edc5c73029a8918b42fffc701b87f69d1a436ca7e33d59fd3b"},{"id":"fee5","topic":"Late payments","clause":"Guest Financial Responsibility","always":false,"q":"You owe $300 in fees and haven't paid it. What applies?","options":[["a","Nothing; I'll pay when I feel like it."],["b","A $20 per day administrative late charge accrues while it's unpaid, and the owner can use the deposit and pursue collection for the rest."],["c","A $20 per day late charge, but only after 30 days have passed, and the owner isn't allowed to take it from my deposit or send it to collections."],["d","Only interest from a court, nothing else."]],"k":"bf9f56047a5898d0424233779310b0b830ba7ccb7ffb9e7c226deadda0aba492"},{"id":"fee6","topic":"Mileage","clause":"Trip Details","always":false,"q":"Your rental includes 200 miles per day. You drive 150 miles more than included. What applies?","options":[["a","Nothing, miles are unlimited."],["b","Extra miles are charged at the daily rate divided by 200, per extra mile."],["c","Extra miles are free if I return the car early, because the unused days cover them."],["d","I'll roll back the odometer."]],"k":"76ea000a24026fb09b1a383797564811b5a91da98867e7b08ae6b0b0558119e2"},{"id":"law1","topic":"Towed or impounded","clause":"Immediate Repossession; Government Action","always":false,"q":"You parked illegally and the car was towed to an impound lot. Who pays?","options":[["a","The owner; the car is registered to them."],["b","I pay all towing, impound and storage fees and any fines, plus the owner's loss of use while it's held."],["c","I pay the parking ticket only. Towing and storage are the owner's cost because the car is registered to them."],["d","I'll leave it there; the owner can get it."]],"k":"55653a6807625d61c722030d977387bdc72170bca874d1b962a1595c39b4d1bc"},{"id":"law2","topic":"Car seized by police","clause":"Government Action","always":false,"q":"Police stop you and seize the car because of something you or a passenger did. What applies?","options":[["a","Not my problem; it's the owner's car."],["b","I'm solely responsible for all fines, towing, storage and other costs, and I indemnify the owner for loss of use and administrative costs."],["c","The passenger who caused it pays the fines and towing, because the agreement only covers what the listed driver personally does with the car."],["d","The owner should get a lawyer for me."]],"k":"f4479e794d4b5d08e5a6e695d2455a00e417084eec1c7db53198356d3fe850ae"},{"id":"prop1","topic":"Keys and accessories","clause":"Ownership; Security Deposit","always":false,"q":"You lose one of the car keys during your rental. What applies?","options":[["a","Keys are cheap, it doesn't matter."],["b","The car must be returned with all keys and accessories. I pay to replace the key, and it can come out of my deposit."],["c","I pay for a replacement key only if the owner has no spare. If a spare exists, losing one key costs nothing and doesn't affect my deposit."],["d","I'll say I never got two keys."]],"k":"e1d8fd0139197529474c93518709793175393e140782e7a4d0b7cd57203d6df4"}]};
